	/**
	 * Keeps only the next fixed-size window in sequence order. Typical directories require one pass. An unusually large
	 * directory is rescanned once per window instead of allocating in proportion to its number of segments.
	 */
	private static final class SegmentCursor {
		private static final Comparator<SegmentEntry> ORDER = Comparator
				.comparingInt((SegmentEntry entry) -> entry.sequence)
				.thenComparing(entry -> entry.path.getFileName().toString());
		private final Path directory;
		private List<SegmentEntry> window = List.of();
		private int position;
		private SegmentEntry after;
		private boolean more = true;

		SegmentCursor(Path directory, Path singleSegment) {
			this.directory = directory;
			if (singleSegment != null) {
				window = List.of(new SegmentEntry(singleSegment, 0));
				more = false;
			}
		}

		SegmentEntry next() throws IOException {
			if (position == window.size()) {
				if (!more) {
					return null;
				}
				loadWindow();
				if (window.isEmpty()) {
					return null;
				}
			}
			return window.get(position++);
		}

		private void loadWindow() throws IOException {
			PriorityQueue<SegmentEntry> next = new PriorityQueue<>(SEGMENT_WINDOW_SIZE, ORDER.reversed());
			more = false;
			if (Files.isDirectory(directory)) {
				try (DirectoryStream<Path> paths = Files.newDirectoryStream(directory)) {
					for (Path path : paths) {
						if (!ValueStoreWAL.SEGMENT_PATTERN.matcher(path.getFileName().toString()).matches()) {
							continue;
						}
						int sequence;
						try {
							sequence = ValueStoreWAL.readSegmentSequence(path);
						} catch (IOException | JacksonException | IllegalArgumentException e) {
							sequence = 0;
						}
						SegmentEntry entry = new SegmentEntry(path, sequence);
						if (after != null && ORDER.compare(entry, after) <= 0) {
							continue;
						}
						if (next.size() < SEGMENT_WINDOW_SIZE) {
							next.add(entry);
						} else {
							more = true;
							if (ORDER.compare(entry, next.peek()) < 0) {
								next.poll();
								next.add(entry);
							}
						}
					}
				}
			}
			window = new ArrayList<>(next);
			window.sort(ORDER);
			position = 0;
			if (!window.isEmpty()) {
				after = window.get(window.size() - 1);
			}
		}
	}

	private static final class Parsed {
		char type = '?';
		long lsn = ValueStoreWAL.NO_LSN;
		int id;
		ValueStoreWalValueKind kind = ValueStoreWalValueKind.NAMESPACE;
		String lex = "";
		String dt = "";
		String lang = "";
		int hash;
		long summaryCrc32;
	}

	@Override
	public void close() {
		closed = true;
		try {
			closeCurrentSegment();
		} catch (IOException e) {
			stop = true;
		}
	}

	/** True only after all segments have been fully consumed and validated. */
	public boolean isComplete() {
		return exhausted && !missingSegments && !summaryMissing && !stop;
	}

	/** Immutable startup metadata, independent of the size of the WAL. */
	public record Summary(long lastValidLsn, int maxId, int contiguousId, boolean hasRecords, boolean complete) {
		public static Summary empty() {
			return new Summary(ValueStoreWAL.NO_LSN, 0, 0, false, true);
		}
	}

	/** Result of a size-limited diagnostic scan. */
	public static final class ScanResult {
		private final List<ValueStoreWalRecord> records;
		private final long lastValidLsn;
		private final boolean complete;

		public ScanResult(List<ValueStoreWalRecord> records, long lastValidLsn, boolean complete) {
			this.records = List.copyOf(records);
			this.lastValidLsn = lastValidLsn;
			this.complete = complete;
		}

		public List<ValueStoreWalRecord> records() {
			return records;
		}

		public long lastValidLsn() {
			return lastValidLsn;
		}

		public boolean complete() {
			return complete;
		}
	}
